  const perQueryTopM = opts.perQueryTopM ?? 6
  const maxMcp = opts.maxMcp ?? 60
  const ids = new Set<string>()
  let keptNonMcp = 0
  const mcpDocs: DocTokens[] = []
  const mcpById = new Map<string, CapabilityEntry>()
  for (const c of capabilities) {
